Task ID: extreme_java_change_impact_longctx
Scenario: 262K extreme Java incident with repeated service implementations and duplicate side-effect logs.

Instructions:
Given the oversized Java approval incident below, identify the smallest safe change set that prevents duplicate user-visible side effects without redesigning the whole service layer.

Project snapshot:

=== File: generated/extreme_java_change_impact.txt ===
# src/main/java/com/example/order/OrderApprovalService.java 1

package com.example.order;

import java.time.Instant;

public class OrderApprovalService {
    private final OrderRepository orderRepository;
    private final AuditRepository auditRepository;
    private final NotificationGateway notificationGateway;

    public OrderApprovalService(
            OrderRepository orderRepository,
            AuditRepository auditRepository,
            NotificationGateway notificationGateway) {
        this.orderRepository = orderRepository;
        this.auditRepository = auditRepository;
        this.notificationGateway = notificationGateway;
    }

    public void approve(long orderId, String operator) {
        Order order = orderRepository.require(orderId);
        order.setStatus("APPROVED");
        orderRepository.save(order);
        notificationGateway.sendApproval(orderId, operator);
        auditRepository.record("ORDER_APPROVED", orderId, Instant.now());
    }
}

